<?php
/** Member 2, Feature 4 - Create allocation form. */
require_once __DIR__.'/../../includes/auth.php';require_role(['admin','production_manager']);
$pageTitle='Allocate Fabric';$currentNav='fabric_allocations';$selectedLot=filter_input(INPUT_GET,'lot_id',FILTER_VALIDATE_INT)?:0;
$lots=[];$batches=[];
try{$res=$conn->query("SELECT fl.fabric_lot_id,fl.lot_number,fl.fabric_type,fl.received_quantity,fl.unit,fl.inspection_status,s.supplier_name,COALESCE(SUM(fa.allocated_quantity),0) allocated_quantity FROM fabric_lots fl JOIN suppliers s ON s.supplier_id=fl.supplier_id LEFT JOIN fabric_allocations fa ON fa.fabric_lot_id=fl.fabric_lot_id WHERE fl.inspection_status IN ('Passed','Conditionally Approved') GROUP BY fl.fabric_lot_id,fl.lot_number,fl.fabric_type,fl.received_quantity,fl.unit,fl.inspection_status,s.supplier_name HAVING fl.received_quantity>COALESCE(SUM(fa.allocated_quantity),0) ORDER BY fl.fabric_lot_id DESC");if($res)$lots=$res->fetch_all(MYSQLI_ASSOC);$res=$conn->query("SELECT pb.batch_id,pb.batch_number,pb.status,bo.order_number,bo.style_number FROM production_batches pb JOIN buyer_orders bo ON bo.order_id=pb.order_id WHERE pb.status<>'Completed' ORDER BY pb.batch_id DESC");if($res)$batches=$res->fetch_all(MYSQLI_ASSOC);}catch(Throwable $e){error_log('Allocation options failed: '.$e->getMessage());}
$errors=$_SESSION['_form_errors']??[];$old=$_SESSION['_form_old']??[];unset($_SESSION['_form_errors'],$_SESSION['_form_old']);if(isset($old['fabric_lot_id']))$selectedLot=(int)$old['fabric_lot_id'];
include __DIR__.'/../../includes/header.php';include __DIR__.'/../../includes/sidebar.php';
?>
<div class="page-header"><div class="page-title-group"><h1>Allocate Fabric</h1><div class="page-subtitle">Allocate an approved lot to a production batch</div></div><div class="page-actions"><a class="btn btn-secondary" href="<?=e(url('modules/fabric_allocations/index.php'))?>">Back to Allocations</a></div></div>
<?php if(!$lots):?><div class="alert alert-warning">No approved fabric with available balance exists. Complete Fabric Inspection first.</div><?php endif?><?php if(!$batches):?><div class="alert alert-warning">No active Production Batch exists.</div><?php endif?>
<div class="card card-form"><div class="card-header"><h2>Allocation Details</h2></div><div class="card-body"><form method="post" action="<?=e(url('modules/fabric_allocations/store.php'))?>" novalidate><?=csrf_field()?>
<div class="form-group"><label class="form-label" for="fabric_lot_id">Approved Fabric Lot <span class="required">*</span></label><select class="form-control <?=isset($errors['fabric_lot_id'])?'has-error':''?>" id="fabric_lot_id" name="fabric_lot_id" required><option value="">-- Select Approved Lot --</option><?php foreach($lots as $l):$available=(float)$l['received_quantity']-(float)$l['allocated_quantity'];?><option value="<?=(int)$l['fabric_lot_id']?>" <?=$selectedLot===(int)$l['fabric_lot_id']?'selected':''?>><?=e($l['lot_number'].' — '.$l['supplier_name'].' — Available '.number_format($available,2).' '.$l['unit'].' — '.$l['inspection_status'])?></option><?php endforeach?></select><?php if(isset($errors['fabric_lot_id'])):?><span class="form-error"><?=e($errors['fabric_lot_id'])?></span><?php endif?></div>
<div class="form-group"><label class="form-label" for="batch_id">Production Batch <span class="required">*</span></label><select class="form-control <?=isset($errors['batch_id'])?'has-error':''?>" id="batch_id" name="batch_id" required><option value="">-- Select Production Batch --</option><?php foreach($batches as $b):?><option value="<?=(int)$b['batch_id']?>" <?=(int)($old['batch_id']??0)===(int)$b['batch_id']?'selected':''?>><?=e($b['batch_number'].' — '.$b['order_number'].' / '.$b['style_number'].' — '.$b['status'])?></option><?php endforeach?></select><?php if(isset($errors['batch_id'])):?><span class="form-error"><?=e($errors['batch_id'])?></span><?php endif?></div>
<div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem"><div class="form-group"><label class="form-label" for="allocated_quantity">Allocated Quantity <span class="required">*</span></label><input class="form-control <?=isset($errors['allocated_quantity'])?'has-error':''?>" type="number" min="0.01" step="0.01" id="allocated_quantity" name="allocated_quantity" value="<?=e($old['allocated_quantity']??'')?>" required><?php if(isset($errors['allocated_quantity'])):?><span class="form-error"><?=e($errors['allocated_quantity'])?></span><?php endif?></div><div class="form-group"><label class="form-label" for="allocated_date">Allocation Date <span class="required">*</span></label><input class="form-control <?=isset($errors['allocated_date'])?'has-error':''?>" type="date" id="allocated_date" name="allocated_date" value="<?=e($old['allocated_date']??date('Y-m-d'))?>" required><?php if(isset($errors['allocated_date'])):?><span class="form-error"><?=e($errors['allocated_date'])?></span><?php endif?></div></div>
<div class="form-group"><label class="form-label" for="notes">Notes</label><textarea class="form-control <?=isset($errors['notes'])?'has-error':''?>" id="notes" name="notes" rows="4" maxlength="2000" placeholder="Roll numbers, cutting issue reference, or allocation note"><?=e($old['notes']??'')?></textarea><?php if(isset($errors['notes'])):?><span class="form-error"><?=e($errors['notes'])?></span><?php endif?></div>
<div class="alert alert-info">The server checks the current balance again inside a database transaction before saving.</div><div class="form-actions"><button class="btn btn-primary" <?=($lots&&$batches)?'':'disabled'?>>Save Allocation</button><a class="btn btn-secondary" href="<?=e(url('modules/fabric_allocations/index.php'))?>">Cancel</a></div></form></div></div>
